'use trialagents v2';
const templateLayoutSchema={"screens":[{"id":"overview","label":"Overview"},{"id":"updates","label":"Updates"},{"id":"investors","label":"Investors"},{"id":"plans","label":"Plans & templates"},{"id":"settings","label":"Settings"}],"groups":{"investors":[{"id":"person","label":"Person"},{"id":"firm","label":"Firm"},{"id":"categories","label":"Categories"},{"id":"classes","label":"Share classes"},{"id":"status","label":"Status"},{"id":"last_read","label":"Last read"},{"id":"email","label":"Email"}],"updates":[{"id":"title","label":"Update"},{"id":"format","label":"Format"},{"id":"categories","label":"Categories"},{"id":"plan","label":"Plan"},{"id":"status","label":"Status"},{"id":"date","label":"Date"},{"id":"read","label":"Read"}]}};
